use flypow_target_protocol as p;
fn goal()->p::GoalSpec{serde_json::from_str(include_str!("../../../web/data/target-mining-v2/brief/goal.json")).unwrap()}
fn input()->p::CandidateInput{p::CandidateInput{stimulated_body_id:"16789".into(),start_step:32,end_step:33,current:150}}
fn archive(g:&p::GoalSpec, mut a:Vec<(u32,u32)>,mut b:Vec<(u32,u32)>)->Vec<u8>{a.sort();b.sort();let mut bytes=vec![0u8;480];bytes[..8].copy_from_slice(b"FBRP1\0\0\0");for (at,n) in [(8,g.neuron_count),(12,g.validate_input(&input()).unwrap()),(16,g.steps),(472,a.len() as u32),(476,b.len() as u32)]{bytes[at..at+4].copy_from_slice(&n.to_le_bytes());}for (at,n) in [(24,a.len() as u64),(32,b.len() as u64)]{bytes[at..at+8].copy_from_slice(&n.to_le_bytes());}for (step,index) in a.into_iter().chain(b){bytes.extend(step.to_le_bytes());bytes.extend(index.to_le_bytes());}bytes}
fn passing(g:&p::GoalSpec)->Vec<(u32,u32)>{g.response_set.iter().flat_map(|m|[(33,m.model_index),(49,m.model_index),(50,m.model_index)]).collect()}
#[test]fn downstream_both_windows_and_full_readout(){let g=goal();g.validate().unwrap();let x=input();let b=passing(&g);let metrics=p::evaluate(&g,&x,&archive(&g,vec![],b.clone())).unwrap();assert!(metrics.passed);assert_eq!(metrics.baseline_spikes,0);assert_eq!(metrics.windows[0].off_target_abs,0);
assert!(!p::evaluate(&g,&x,&archive(&g,vec![],vec![(33,g.stimulus_set[0].model_index)])).unwrap().passed);
assert!(!p::evaluate(&g,&x,&archive(&g,vec![],b.iter().copied().filter(|e|e.0<49).collect())).unwrap().passed);
let broad=b.iter().copied().chain(g.off_target_set.iter().flat_map(|m|(33..81).map(move|s|(s,m.model_index)))).collect();assert!(!p::evaluate(&g,&x,&archive(&g,vec![],broad)).unwrap().passed);
let with_a=archive(&g,b.clone(),b);assert!(!p::evaluate(&g,&x,&with_a).unwrap().passed);
}
#[test]fn archive_order_count_boundaries_and_canonical_input(){let g=goal();let mut bytes=archive(&g,vec![],passing(&g));assert!(p::evaluate(&g,&input(),&bytes).is_ok());bytes.push(0);assert!(p::evaluate(&g,&input(),&bytes).is_err());let bytes=archive(&g,vec![],vec![(33,g.response_set[0].model_index);2]);assert!(p::evaluate(&g,&input(),&bytes).is_err());let mut x=input();x.end_step=x.start_step;assert!(g.validate_input(&x).is_err());x=input();x.current=u32::MAX;assert!(g.validate_input(&x).is_err());x=input();x.stimulated_body_id="016789".into();assert!(g.validate_input(&x).is_err());let mut too_big=g;too_big.input_domain.starts=(0..256).collect();too_big.input_domain.durations=(1..257).collect();too_big.input_domain.currents=(1..257).collect();too_big.input_domain_hash=p::id("input-domain",&p::value(&too_big.input_domain)).unwrap();assert!(too_big.validate().is_err());}
#[test]fn maximum_controller_level_reachable(){use p::difficulty::*;let levels=[2,4].into_iter().enumerate().map(|(i,r)|Level{profile_id:format!("r{r}"),required_backgrounds:r,difficulty_micros:(i as u64+1)*1_000_000,calibration_hash:"a".repeat(64),enabled:true}).collect::<Vec<_>>();let mut c=Controller::new("family".into(),&levels,300000).unwrap();for at in 1..50{c.observe(&levels,"family",at,Some(1),true).unwrap();}assert_eq!(c.applied_index,1);assert_eq!(c.desired_micros,2_000_000);for at in 50..150{c.observe(&levels,"family",at,Some(3000000),true).unwrap();}assert_eq!(c.applied_index,0);}
